// Doorbell chime: a settled press sounds the chime for 300 ms.
// Chime driver on D7, doorbell button on D4 (pull-up), status over UART.

const int CHIME_PIN = 7;
const int BUTTON_PIN = 4;
const unsigned long CHIME_MS = 300;
const unsigned long REPORT_MS = 1000;
const int POLL_MS = 5;
const unsigned long CONFIRM_MS = 20;

bool lowActive = false;
unsigned long lowStart = 0;
bool armed = true;
bool chiming = false;
unsigned long chimeStart = 0;
unsigned long lastReport = 0;
unsigned int rings = 0;

void startChime()
{
    chiming = true;
    chimeStart = millis();
    rings++;
    digitalWrite(CHIME_PIN, HIGH);
}

void endChime()
{
    chiming = false;
    digitalWrite(CHIME_PIN, LOW);
}

void pollButton()
{
    if (digitalRead(BUTTON_PIN) == LOW)
    {
        if (!lowActive)
        {
            lowActive = true;
            lowStart = millis();
        }
        if (armed && millis() - lowStart >= CONFIRM_MS)
        {
            armed = false;
            if (!chiming)
            {
                startChime();
            }
        }
    }
    else
    {
        lowActive = false;
        armed = true;
    }
}

void report()
{
    Serial.print("chime n=");
    Serial.println(rings);
}

void setup()
{
    pinMode(CHIME_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    digitalWrite(CHIME_PIN, LOW);
    Serial.begin(9600);
    lastReport = millis();
}

void loop()
{
    pollButton();
    if (chiming && millis() - chimeStart >= CHIME_MS)
    {
        endChime();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
    delay(POLL_MS);
}

// Lift call panel: buzzer acknowledges a press, a status line shows the
// panel is alive. Buzzer on D11, call button on D5 (pull-up).

const int BUZZER_PIN = 11;
const int BUTTON_PIN = 5;
const unsigned long BUZZ_MS = 300;
const unsigned long SETTLE_MS = 5;
const unsigned long BEAT_MS = 500;

int rawLevel = HIGH;
bool held = false;
unsigned long rawChangedAt = 0;
unsigned long lastBeat = 0;
unsigned int beats = 0;
bool buzzing = false;
unsigned long buzzStartedAt = 0;

void startBuzz()
{
    digitalWrite(BUZZER_PIN, HIGH);
    buzzing = true;
    buzzStartedAt = millis();
}

void serviceBuzz()
{
    if (buzzing && millis() - buzzStartedAt >= BUZZ_MS)
    {
        digitalWrite(BUZZER_PIN, LOW);
        buzzing = false;
    }
}

void scanButton()
{
    int level = digitalRead(BUTTON_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !buzzing)
        {
            startBuzz();
        }
        held = down;
    }
}

void heartbeat()
{
    beats++;
    Serial.print("alive ");
    Serial.println(beats);
}

void setup()
{
    pinMode(BUZZER_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    digitalWrite(BUZZER_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastBeat = millis();
}

void loop()
{
    scanButton();
    serviceBuzz();
    if (millis() - lastBeat >= BEAT_MS)
    {
        lastBeat += BEAT_MS;
        heartbeat();
    }
}

// Meadow sprinkler zone: one 500 ms burst per start press.
// Valve relay on D10, start button on D6 (pull-up), status over UART.

const int ZONE_PIN = 10;
const int START_PIN = 6;
const unsigned long BURST_MS = 500;
const unsigned long SETTLE_MS = 15;
const unsigned long REPORT_MS = 1000;

bool zoneOpen = false;
bool held = false;
int rawLevel = HIGH;
unsigned long rawChangedAt = 0;
unsigned long closeAt = 0;
unsigned long lastReport = 0;
unsigned int bursts = 0;

void openZone()
{
    zoneOpen = true;
    closeAt = millis() + BURST_MS;
    digitalWrite(ZONE_PIN, HIGH);
    bursts++;
}

void closeZone()
{
    zoneOpen = false;
    digitalWrite(ZONE_PIN, LOW);
}

bool closeDue()
{
    return (long)(millis() - closeAt) >= 0;
}

void scanStart()
{
    int level = digitalRead(START_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !zoneOpen)
        {
            openZone();
        }
        held = down;
    }
}

void report()
{
    Serial.print("zone n=");
    Serial.println(bursts);
}

void setup()
{
    pinMode(ZONE_PIN, OUTPUT);
    pinMode(START_PIN, INPUT_PULLUP);
    digitalWrite(ZONE_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanStart();
    if (zoneOpen && closeDue())
    {
        closeZone();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Orchard spray controller: one short burst per trigger press.
